import lab
from machine import Pin, PWM
servo = PWM(Pin(17), freq=50)
def angle(a):
    servo.duty_u16(int((0.5 + a / 180 * 2.0) / 20 * 65535))
while lab.running():
    for a in (0, 90, 180, 90):
        angle(a)
        lab.sleep(0.6)

