import lab, dht
from machine import Pin
s = dht.DHT22(Pin(18))
while lab.running():
    try:
        s.measure()
        print('溫度', s.temperature(), '濕度', s.humidity())
    except OSError as e:
        print('讀取失敗', e)
    lab.sleep(2)

stepper.code:
import lab
from machine import Pin
pins = [Pin(16, Pin.OUT), Pin(17, Pin.OUT), Pin(18, Pin.OUT), Pin(48, Pin.OUT)]
seq = ['1000', '1100', '0100', '0110', '0010', '0011', '0001', '1001']
while lab.running():
    for s in seq:
        for p, v in zip(pins, s):
            p.value(int(v))
        lab.sleep(0.005)
